import{_ as o,l,o as e,c as r,v as t,p as s,x as n,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"nanosheet 间距","description":"","frontmatter":{"title":"nanosheet 间距","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/nanosheet-spacing.md","filePath":"litho/nanosheet-spacing.md","lastUpdated":1789023840000}'),A={name:"litho/nanosheet-spacing.md"};function c(E,a,m,P,f,_){const i=l("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="nanosheet-间距" tabindex="-1">nanosheet 间距 <a class="header-anchor" href="#nanosheet-间距" aria-label="Permalink to &quot;nanosheet 间距&quot;">​</a></h1><div class="epigraph"><p>GAA 把有效宽度交给片宽和片数；片与片之间的垂直间距是填充窗口，横向节距仍是光刻合同。</p><footer>—— 对照 imec 对 nanosheet / GAA 几何与间距的公开展望</footer></div><p><a href="/litho/finfet-gaa">上一课</a>把沟道从三面鳍换成四面纳米片，并点名释放刻蚀与内间隔。缺口是几何里那几段「间距」各由谁决定：哪些是外延/刻蚀，哪些仍是光刻 CD。本课钉 nanosheet 间距。背面供电如何改布线，留给<a href="/litho/backside-power">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FinFET 的鳍节距是前道光刻加多重图形的硬节距。GAA 纳米片把<strong>垂直</strong>方向的片厚、片间距交给外延超晶格和释放，片与片之间要留给内间隔和功函数金属的填充缝。间距太小，<a href="/litho/ald-ale">ALD</a> 填不进、阈值分裂；太大，堆叠高度涨，后段介质与寄生一起坏。imec 公开讨论把这组垂直几何写成器件截面预算，而不是又一层 EUV。</p><p>横向仍要光刻：片宽（几乎连续可调的 Weff）、器件隔离、假栅/替换栅节距（CPP）、接触。上一课的静电学故事若没有横向节距，单元高度下不来。缺口是把「间距」拆开，避免把所有纳米都写成光刻。</p><h3 id="片宽不是鳍节距的换皮" tabindex="-1">片宽不是鳍节距的换皮 <a class="header-anchor" href="#片宽不是鳍节距的换皮" aria-label="Permalink to &quot;片宽不是鳍节距的换皮&quot;">​</a></h3><p>鳍宽被量化，且与鳍节距耦合。纳米片宽度在浅槽前由设计画，密隔离与宽驱动可以在同一高度下并存。限制它的是光刻与隔离填充，以及释放后片的机械下垂。横向最小间距仍服从 \\(k_1\\lambda/\\mathrm{NA}\\) 与多重图形，GAA 并不赠送一层免费分辨率。</p><p><span class="marginnote">Nanosheet、MBCFET、RibbonFET 的公开片数、片厚不同。写间距用截面角色（片厚、片缝、CPP、隔离），不要把产品名换算成唯一纳米表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>垂直：Si/SiGe 周期决定片厚与牺牲层厚；释放后的空腔 = 片缝。内间隔从空腔里「吃掉」一部分横向栅漏电容空间，剩余才是金属填充窗。这串步骤的变差是 ALE/选择性刻蚀变差，不是扫描机剂量。</p><p>横向：片宽 OPC 按隔离环境修；CPP 与鳍/片阵列节距仍走前道 EUV 或多重 DUV。接触孔与通孔见接触课。DTCO 用片宽档换驱动，用垂直片数换电流密度，用 CPP 换密度——三个旋钮来源不同。</p><h3 id="imec-截面里的光刻可读点" tabindex="-1">imec 截面里的光刻可读点 <a class="header-anchor" href="#imec-截面里的光刻可读点" aria-label="Permalink to &quot;imec 截面里的光刻可读点&quot;">​</a></h3><p>公开截面强调：片缝给 WK 金属；forksheet 用介电墙再削 N/P 间距——墙的位置又回到横向光刻与刻蚀。读 imec 图时先标：哪条尺寸是外延周期，哪条是光刻 CD。本课只训练这张读法。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自然长度吃片厚；寄生电容吃片缝和内间隔；密度吃 CPP 与隔离。光刻能直接动的是后两者的横向部分。垂直片缝若为填充让路而加大，芯片高度涨，BEOL 地形变难，<a href="/litho/beol-euv">后道 EUV</a> 的焦深更紧。所以器件课的间距会反馈到后道光刻，不是单向的。</p><p>片下垂与粘连：释放后片是梁，间距与片宽决定刚度。过宽的片在过大空腔下更易变形，变成良率而不是 OPC 问题。</p><p><span class="marginnote">不要把实验室 CFET 的垂直 N/P 间距写进当前 nanosheet 量产间距表。CFET 是后续课的拓扑。</span></p>',18)),(e(),s(d,null,{default:n(()=>[p(i,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20VERT%5B%22%E5%A4%96%E5%BB%B6%E7%89%87%E5%8E%9A%20%2F%20%E7%89%87%E7%BC%9D%22%5D%20--%3E%20FILL%5B%22%E5%86%85%E9%97%B4%E9%9A%94%20%2B%20ALD%20%E5%A1%AB%E5%85%85%22%5D%0A%20%20LAT%5B%22%E5%85%89%E5%88%BB%3A%20%E7%89%87%E5%AE%BD%20%2F%20CPP%20%2F%20%E9%9A%94%E7%A6%BB%22%5D%20--%3E%20DTCO%5B%22Weff%20%E4%B8%8E%E5%8D%95%E5%85%83%E5%AF%86%E5%BA%A6%22%5D%0A%20%20FILL%20--%3E%20PARA%5B%22%E5%AF%84%E7%94%9F%E4%B8%8E%E9%AB%98%E5%BA%A6%22%5D%0A%20%20LAT%20--%3E%20PARA%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写 FinFET 静电学推导，也不给未公开的片缝纳米规格。不要发明 imec 某张幻灯片上的精确 nm 当作标准。片数（公开讨论常见三至四片）是垂直电流档，与横向隔离节距独立：加片不加平面脚印，但加高度。后课默认：GAA 间距要问垂直还是横向、工艺还是光刻。</p><p>引用 imec GAA / nanosheet 公开技术论述。</p><p><span class="marginnote">片宽连续可调，仍受 MRC 与隔离规则离散化。库不会真的按 1 nm 一档无限枚举。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>垂直片厚/片缝主要是外延与释放；横向片宽、CPP、隔离仍是光刻。</li><li>片缝是 WK 金属与内间隔的填充窗，太小填不满，太大高度与寄生涨。</li><li>GAA 不取消前道节距缩放。</li><li>器件高度会反馈后道地形与焦深。</li><li>forksheet 的介电墙把 N/P 横向间距再交给光刻与刻蚀。</li><li>片下垂与粘连是释放后的机械问题，不是 OPC 能修的边。</li><li>出处：imec nanosheet / GAA 公开展望。</li></ul>',6))])}const T=o(A,[["render",c]]);export{B as __pageData,T as default};
